cd "C:\visual projects\alpha" && python3 -c "
def process(path, lo, hi):
    with open(path, encoding='utf-8') as f:
        lines = f.readlines()
    for i in range(lo-1, hi):
        line = lines[i]
        if not line.startswith('|'):
            continue
        raw = line.rstrip('\n')
        cells = raw.strip('|').split('|')
        cells = [c.strip() for c in cells]
        if len(cells) < 3:
            continue
        if cells[0] == 'параметр':
            continue
        if set(''.join(cells[0])) <= set('-: '):
            continue
        main = cells[1]
        variants = cells[2:]
        print(f'--- line {i+1} param={cells[0]!r}')
        print('   MAIN:', main[:80])
        for j, v in enumerate(variants):
            marker = ''
            if v.startswith('как у главного'):
                marker = '[REPLACE]'
            elif '**' in v:
                marker = '[BOLD-DIFF]'
            elif v != main:
                marker = '[PLAIN-DIFF?]'
            print(f'   v{j}: {marker} {v[:100]}')

process('docs/research/P-07-g85-titration.md', 447, 511)
"

